class Money:
    def __init__(self, v):
        self.v = v
    def __eq__(self, other):
        return self.v == other.v
    def __add__(self, other):
        return Money(self.v + other.v)

print(Money(2) == Money(2))
print((Money(2) + Money(3)).v)

